package orchestrator.auth

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

case class Tenant(id: String, namespace: String, apiKeyHash: Array[Byte])
case class ContainerSpec(image: String, cpu: Int, memory: Int, tenantId: String)
case class AuthResult(authenticated: Boolean, tenant: Option[Tenant])

object TenantRegistry {
  private val tenants = new ConcurrentHashMap[String, Tenant]()
  private val rateLimits = new ConcurrentHashMap[String, Long]()
  private val MAX_REQUESTS_PER_SECOND = 100

  def register(id: String, namespace: String, apiKey: String): Unit = {
    val hash = computeHmac(apiKey, id)
    tenants.put(id, Tenant(id, namespace, hash))
  }

  def getTenant(id: String): Option[Tenant] = Option(tenants.get(id))

  def computeHmac(data: String, key: String): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(key.getBytes("UTF-8"), "HmacSHA256")
    mac.init(keySpec)
    mac.doFinal(data.getBytes("UTF-8"))
  }
}

trait IsolationPolicy {
  def validateAccess(tenant: Tenant, spec: ContainerSpec): Boolean
  def enforceNamespace(tenant: Tenant, targetNamespace: String): Boolean
}

class StrictIsolation extends IsolationPolicy {
  override def validateAccess(tenant: Tenant, spec: ContainerSpec): Boolean = {
    tenant.id == spec.tenantId
  }

  override def enforceNamespace(tenant: Tenant, targetNamespace: String): Boolean = {
    tenant.namespace == targetNamespace
  }
}

object AuthenticationService {
  private val isolation: IsolationPolicy = new StrictIsolation()
  private val failedAttempts = new ConcurrentHashMap[String, Int]()
  private val LOCKOUT_THRESHOLD = 5

  def authenticate(tenantId: String, providedKey: String): AuthResult = {
    if (isLockedOut(tenantId)) {
      return AuthResult(authenticated = false, None)
    }

    TenantRegistry.getTenant(tenantId) match {
      case Some(tenant) =>
        val providedHash = TenantRegistry.computeHmac(providedKey, tenantId)
        if (verifyKeyConstantTime(tenant.apiKeyHash, providedHash)) {
          failedAttempts.remove(tenantId)
          AuthResult(authenticated = true, Some(tenant))
        } else {
          recordFailure(tenantId)
          AuthResult(authenticated = false, None)
        }
      case None =>
        AuthResult(authenticated = false, None)
    }
  }

  private def verifyKeyConstantTime(expected: Array[Byte], provided: Array[Byte]): Boolean = {
    if (expected.length != provided.length) return false
    var result: Int = 0
    var i = 0
    while (i < expected.length) {
      result |= (expected(i) ^ provided(i))
      i += 1
    }
    result == 0
  }

  private def isLockedOut(tenantId: String): Boolean = {
    Option(failedAttempts.get(tenantId)).exists(_ >= LOCKOUT_THRESHOLD)
  }

  private def recordFailure(tenantId: String): Unit = {
    failedAttempts.merge(tenantId, 1, (a: Int, b: Int) => a + b)
  }

  def authorizeDeployment(authResult: AuthResult, spec: ContainerSpec): Boolean = {
    authResult match {
      case AuthResult(true, Some(tenant)) =>
        isolation.validateAccess(tenant, spec)
      case _ => false
    }
  }
}

object ContainerOrchestrator {
  private val deployments = new ConcurrentHashMap[String, mutable.ListBuffer[ContainerSpec]]()

  def deploy(tenantId: String, apiKey: String, spec: ContainerSpec): Either[String, String] = {
    val authResult = AuthenticationService.authenticate(tenantId, apiKey)
    if (!authResult.authenticated) {
      return Left("Authentication failed")
    }

    if (!AuthenticationService.authorizeDeployment(authResult, spec)) {
      return Left("Authorization failed: cross-tenant access denied")
    }

    val tenantDeployments = deployments.computeIfAbsent(
      tenantId, _ => mutable.ListBuffer[ContainerSpec]()
    )
    tenantDeployments.synchronized {
      tenantDeployments += spec
    }
    Right(s"Container ${spec.image} deployed in namespace ${authResult.tenant.get.namespace}")
  }

  def listDeployments(tenantId: String, apiKey: String): Either[String, List[ContainerSpec]] = {
    val authResult = AuthenticationService.authenticate(tenantId, apiKey)
    if (!authResult.authenticated) {
      return Left("Authentication failed")
    }

    val tenantDeployments = Option(deployments.get(tenantId))
    Right(tenantDeployments.map(_.toList).getOrElse(List.empty))
  }
}
